export const CapacityResponseRecommendationBandIssues = {
  ok: 'ok',
  warn: 'warn',
  over: 'over',
} as const;

export type CapacityResponseRecommendationBand = {
  sp: CapacityResponseRecommendationBandSp;
  issues: CapacityResponseRecommendationBandIssues;
};

export type CapacityResponseRecommendation = {
  range: CapacityRange;
  availabilityPct: number;
  availablePersonDays: number;
  band: CapacityResponseRecommendationBand;
} | null;

export type CapacityResponseCommitted = {
  sp: number;
  issues: number;
  unestimated: number;
};

export type CapacityResponseProgressPaceSp = typeof CapacityResponseProgressPaceSp[keyof typeof CapacityResponseProgressPaceSp];


export const CapacityResponseProgressPaceSp = {
  ok: 'ok',
  warn: 'warn',
  over: 'over',
} as const;

export type CapacityResponseProgressPaceIssues = typeof CapacityResponseProgressPaceIssues[keyof typeof CapacityResponseProgressPaceIssues];


export const CapacityResponseProgressPaceIssues = {
  ok: 'ok',
  warn: 'warn',
  over: 'over',
} as const;

export type CapacityResponseProgressPace = {
  sp: CapacityResponseProgressPaceSp;
  issues: CapacityResponseProgressPaceIssues;
} | null;

/**
 * Only for the active sprint.
 */
export type CapacityResponseProgress = {
  elapsedDays: number;
  remainingDays: number;
  done: CapacityUnits;
  remaining: CapacityUnits;
  /** Recommended range prorated to the elapsed share of the sprint. */
  expected: CapacityRange | null;
  pace: CapacityResponseProgressPace;
} | null;

export type CapacityResponseRate = {
  sp: CapacityRateBand;
  issues: CapacityRateBand;
  sprintsUsed: number;
} | null;

export interface CapacityResponse {
  sprint: CapacityResponseSprint;
  recommendation: CapacityResponseRecommendation;
  committed: CapacityResponseCommitted;
  /** Only for the active sprint. */
  progress: CapacityResponseProgress;
  rate: CapacityResponseRate;
  team: CapacityTeamRow[];
  unassigned: CapacityUnits;
  teamSummary: CapacityTeamSummary;
  history: CapacityHistoryRow[];
  warnings: string[];
}

export interface WeekMetric {
  /** ISO date of the Monday of this week */
  weekStart: string;
  /** Human-readable label like "Mar 2 - Mar 8" */
  weekLabel: string;
  /** Issues completed this week (throughput) */
  totalIssues: number;
  totalStoryPoints: number;
  /** @nullable */
  avgCycleTimeDays: number | null;
  /** @nullable */
  medianCycleTimeDays: number | null;
  reopenedCount: number;
  breakdown: IssueTypeBreakdown;
}

export interface KanbanMetricsSummary {
  totalWeeks: number;
  avgThroughput: number;
  /** @nullable */
  avgCycleTimeDays: number | null;
  /** @nullable */
  medianCycleTimeDays: number | null;
  totalCompletedIssues: number;
  totalCompletedStoryPoints: number;
}

export interface KanbanMetricsResponse {
  weeks: WeekMetric[];
  summary: KanbanMetricsSummary;
}

